INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('xixia','西夏','["大夏","党项西夏"]','党项','cn','east_asia',982,1,NULL,'year',1227,1,NULL,'year',11784,14724,'ochre',NULL,NULL,'党项李氏原据夏州一带，李继迁时期逐步摆脱宋朝控制并扩展至河西；1038年李元昊称帝，国号大夏，定都兴庆府，宋人因其地在西而称西夏。西夏在党项旧制基础上设置官僚机构，创制并推行西夏文字，翻译佛经、发展佛教文化。其政权与北宋、辽长期并立，先后交战、议和并开展贸易；金灭辽后，又处于宋金之间。蒙古自13世纪初持续进攻，1227年西夏为蒙古所灭。');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('li-anquan','李安全','xixia','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','夏仁宗侄、夏襄宗，废黜李纯佑后即位，依靠外戚势力执政。蒙古于1209年大举攻夏，西夏被迫求和并承受持续压力；1211年李遵顼发动政变夺位；在位1206—1211年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/李安全"}]','敬穆皇帝','襄宗','夏襄宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('li-bingchang','李秉常','xixia','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','夏毅宗之子、夏惠宗，幼年继位后先由梁太后掌政，亲政尝试收回权力时与母后及外戚冲突。宋夏战争反复，梁氏重新控制朝政，他在位期间王权受到外戚牵制；在位1067—1086年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/李秉常"}]','昭简皇帝','惠宗','夏惠宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('li-chunyou','李纯佑','xixia','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','夏仁宗之子、夏桓宗，承接相对稳定的西夏政局。其在位后期蒙古势力兴起并向西北扩张，1206年被李安全废黜；在位1193—1206年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/李纯佑"}]','昭简皇帝','桓宗','夏桓宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('li-deming','李德明','xixia','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','李继迁之子，1004年父死后继承党项李氏势力。与宋、辽分别交涉，1006年接受宋朝册封，维持边境互市并经营农业；在兴庆营建统治中心，向河西扩张，为李元昊称帝积累地域与经济基础。1032年去世，李元昊继位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/李德明"},{"label":"宋史/卷485","url":"https://zh.wikisource.org/wiki/宋史/卷485"}]',NULL,NULL,'西夏王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('li-dewang','李德旺','xixia','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','李遵顼之子、夏献宗，继位时西夏已承受蒙古长期侵攻。其在位期间尝试联合金朝抵抗蒙古，但战局持续恶化，1226年由李睍继位；在位1223—1226年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/李德旺"}]','南平王','献宗','夏献宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('li-jiqian','李继迁','xixia','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','党项李氏宗族成员。982年族兄李继捧将夏州等地献宋后，李继迁率部退往地斤泽，联结党项部落反宋，985年攻取银州。借与辽结盟和对宋战争扩大势力，1002年夺取灵州，为西夏建立地域基础；1004年去世，子李德明继承。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/李继迁"}]','光天皇帝','太祖','夏太祖','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('li-liangzuo','李谅祚','xixia','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','李元昊之子，夏毅宗，幼年即位，由没藏太后及其兄没藏讹庞辅政。亲政后调整对宋关系并推动制度建设，后来在宫廷政变后由梁氏家族掌权；在位1048—1067年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/李谅祚"}]','昭英皇帝','毅宗','夏毅宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('li-qianshun','李乾顺','xixia','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','夏惠宗之子、夏崇宗，幼年即位，梁太后长期摄政，后亲政并维持西夏统治。其五十余年在位横跨宋辽对峙、金朝崛起及金灭辽后格局变化，西夏在此期间延续并巩固其国家制度；在位1086—1139年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/李乾顺"}]','康靖皇帝','崇宗','夏崇宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('li-renxiao','李仁孝','xixia','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','夏崇宗之子、夏仁宗，在位期间整顿典章、尊崇儒学并发展学校与科举制度，推动西夏汉文和党项文字文教。其朝与金、南宋保持相对稳定的外交关系，西夏文化发展达到重要阶段；在位1139—1193年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/李仁孝"}]','圣德皇帝','仁宗','夏仁宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('li-xian-xixia','李睍','xixia','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','夏献宗之后继位的西夏末帝李睍，蒙古军攻夏期间即位，统治区域迅速收缩。1227年蒙古军攻灭西夏，他出降后被杀，西夏政权终结；在位1226—1227年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/李睍"}]',NULL,NULL,'夏末帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('li-yuanhao','李元昊','xixia','[]',NULL,NULL,1003,1,NULL,'year',1048,1,NULL,'year','["皇帝"]','李德明之子，继承祖父李继迁、父李德明经营的党项政权。参与向河西扩张，1032年父死后继掌夏州势力，进一步取得瓜州、沙州等地。1038年称帝，国号大夏；创制西夏文字并改革官制，多次与宋交战，1044年议和，1048年被子李宁令哥刺伤后去世。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/李元昊"},{"label":"宋史/卷485","url":"https://zh.wikisource.org/wiki/宋史/卷485"}]','武烈皇帝','景宗','夏景宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('li-zunxu','李遵顼','xixia','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','西夏宗室、夏神宗，以政变推翻李安全后即位。蒙古军持续进攻之际，他一度主动伐金以求缓解压力，却使西夏陷入更不利的外交与军事处境，后传位于子李德旺；在位1211—1223年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/李遵顼"}]','英武皇帝','神宗','夏神宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liang-taihou-xixia','梁太后','xixia','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["后妃","政治家"]','惠宗李秉常之母，两度摄政，主张对宋用兵；她与梁氏外戚掌权期间，西夏多次与宋交战；个人生卒记载有限。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/梁太后"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('mo-nang-e-pang','没藏讹庞','xixia','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["政治家","军事家"]','西夏权臣，毅宗朝没藏太后之父，长期摄政干政；他与没藏太后权势日增，后因擅权与太后决裂，遭夏毅宗诛杀。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/没藏讹庞"}]',NULL,NULL,NULL,'[]');
